@RestController
@RequestMapping("/api/v{version}/users")
public class UserController {
    @GetMapping("/{id}")
    public Mono<UserDto> getUser(@PathVariable String version, @PathVariable String id) {
        if ("1".equals(version)) return userService.findByIdV1(id);
        return userService.findByIdV2(id);
    }
}
